    def components(color):
        seen = set()
        result = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            stack.append((nx, ny))
                result.append(cells)
        return result

    def normalize(cells):
        r0 = min(r for r, c in cells)
        c0 = min(c for r, c in cells)
        return frozenset((r-r0, c-c0) for r, c in cells)

    def rotations(cells):
        pts = list(cells)
        forms = set()
        for _ in range(4):
            r0 = min(r for r, c in pts)
            c0 = min(c for r, c in pts)
            forms.add(frozenset((r-r0, c-c0) for r, c in pts))
            pts = [(c, -r) for r, c in pts]
        return forms

    references = []
    for color in range(2, 10):
        for cells in components(color):
            references.append((color, normalize(cells), rotations(cells)))

    out = [row[:] for row in grid]
